package org.apache.commons.lang;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ClassUtils.getShortClassName
 */
public class ClassUtils_getShortClassName_TriageGen2Test {

    private static final String PACKAGE_SEPARATOR_CHAR = ".";
    private static final String INNER_CLASS_SEPARATOR_CHAR = "$";

    @Test
    public void testGetShortClassName_NullInput() {
        String result = ClassUtils.getShortClassName(null);
        assertEquals(StringUtils.EMPTY, result);
    }

    @Test
    public void testGetShortClassName_EmptyInput() {
        String result = ClassUtils.getShortClassName("");
        assertEquals(StringUtils.EMPTY, result);
    }

    @Test
    public void testGetShortClassName_SimpleClassName() {
        // Case where there is no dot (no package)
        String className = "java.lang.String";
        // lastDotIdx = 10
        // innerIdx = -1
        // out = substring(11) -> "String"
        assertEquals("String", ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_NoPackage() {
        // Case where there is no package separator
        String className = "MyClass";
        // lastDotIdx = -1
        // innerIdx = indexOf('$', 0) -> -1
        // out = substring(0) -> "MyClass"
        assertEquals("MyClass", ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_WithInnerClass() {
        // Case where there is a package and an inner class ($)
        // Note: The logic replaces $ with . for the output
        String className = "com.example.OuterClass$InnerClass";
        // lastDotIdx = 12 (after 'example')
        // innerIdx = className.indexOf('$', 13) -> 24
        // out = className.substring(13) -> "OuterClass$InnerClass"
        // since innerIdx != -1, out = "OuterClass.InnerClass"
        assertEquals("OuterClass.InnerClass", ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_WithMultipleDotsAndInnerClass() {
        String className = "org.apache.commons.lang.ClassUtils$Inner";
        // lastDotIdx = 25 (after 'lang')
        // innerIdx = className.indexOf('$', 26) -> 35
        // out = substring(26) -> "ClassUtils$Inner"
        // replace $ with . -> "ClassUtils.Inner"
        assertEquals("ClassUtils.Inner", ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_InnerClassWithoutPackage() {
        // Case where there is no package, but there is an inner class symbol
        String className = "Outer$Inner";
        // lastDotIdx = -1
        // innerIdx = className.indexOf('$', 0) -> 5
        // out = substring(0) -> "Outer$Inner"
        // replace $ with . -> "Outer.Inner"
        assertEquals("Outer.Inner", ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_DotAtEnd() {
        // Edge case: dot at the end
        String className = "com.example.";
        // lastDotIdx = 11
        // innerIdx = -1
        // out = substring(12) -> ""
        assertEquals("", ClassUtils.getShortClassName(className));
    }
}
